    let localVelocityDiv = lerpResult0.unpacked;

    let lerpResult1 = tex1Dlod_lerp(internalTex1, internalTex1Sampler, vec2f(nlife, 0.0));
    var velocity = lerpResult1.result;
    let velocityDiv = lerpResult1.unpacked;

